        assign_depots(net, ["D1", "D2"], ["C1"]) == {"C1": "D1"}
    """
    assignments = {}

    # Validate all inputs exist in adj first to satisfy the KeyError requirement
    for d in depots:
        if d not in adj:
            raise KeyError(d)
    for c in customers:
        if c not in adj:
            raise KeyError(c)

    for customer in customers:
        best_depot = None
        # (distance, legs, depot_code)
        best_metric = (float('inf'), float('inf'), "")

        for depot in depots:
            result = shortest_path(adj, depot, customer)
