import heapq
from typing import Mapping, Optional, Tuple, List

def shortest_path(adj: Mapping[str, Mapping[str, int]], src: str, dst: str) -> Optional[Tuple[int, List[str]]]:
    """
    Find the shortest route between two depots with deterministic tie-breaking.
    Tie rule: among routes with the same total km, the one with fewer legs wins;
    if they also have the same number of legs, the lexicographically smallest
    list of depot codes wins.
    """
    if src not in adj:
        return None
    if src == dst:
        return (0, [src])

    # Priority Queue stores: (distance, num_legs, path)
    # Dijkstra's with tie-breaking
    pq = [(0, 0, [src])]
    visited = {}

    while pq:
        dist, legs, path = heapq.heappop(pq)
        u = path[-1]

        if u == dst:
            return (dist, path)

        if u in visited and visited[u] <= (dist, legs, path):
            continue
        visited[u] = (dist, legs, path)

        for v, weight in adj.get(u, {}).items():
            new_dist = dist + weight
            new_legs = legs + 1
            new_path = path + [v]
            if v not in visited or (new_dist, new_legs, new_path) < visited[v]:
                heapq.heappush(pq, (new_dist, new_legs, new_path))

    return None
