from typing import Iterable, List, Tuple, Set, Dict
from collections import deque
from routekit.build_adjacency import build_adjacency


def _is_reachable(adj: Dict[str, Dict[str, int]], start: str, target: str) -> bool:
    """Check if target is reachable from start using BFS."""
    if start not in adj or target not in adj:
        return False

    visited: Set[str] = {start}
    queue = deque([start])

    while queue:
        u = queue.popleft()
        if u == target:
            return True
        for v in adj.get(u, {}):
            if v not in visited:
                visited.add(v)
                queue.append(v)
    return False


def critical_roads(edges: Iterable[Tuple[str, str, int]]) -> List[Tuple[str, str]]:
    """
    Find the roads whose closure would cut a region in two.

    Roads are undirected and the network is built with ``build_adjacency``. A road
    between depots ``a`` and ``b`` is critical if, once it is closed, ``b`` can no
    longer be reached from ``a``. Self-loops are never critical. Networks are small (a
    few dozen roads), so checking each road separately is fine.

    Returns the critical roads as ``(code_a, code_b)`` pairs with ``code_a < code_b``,
    sorted, each road listed once.

    Example:
        critical_roads([("A", "B", 1), ("B", "C", 1), ("C", "A", 1), ("C", "D", 4)]) == [("C", "D")]
    """
    edge_list = list(edges)
    if not edge_list:
        return []

    pair_counts: Dict[Tuple[str, str], int] = {}
    for u, v, w in edge_list:
        if u == v:
            continue
        pair = tuple(sorted((u, v)))
        pair_counts[pair] = pair_counts.get(pair, 0) + 1

    potential_pairs = [pair for pair, count in pair_counts.items() if count == 1]

    critical = []
    for u_crit, v_crit in potential_pairs:
        filtered_edges = []
        removed = False
        for u, v, w in edge_list:
            if not removed and tuple(sorted((u, v))) == (u_crit, v_crit):
                removed = True
                continue
            filtered_edges.append((u, v, w))

        adj = build_adjacency(filtered_edges)
        if not _is_reachable(adj, u_crit, v_crit):
            critical.append((u_crit, v_crit))

    return sorted(critical)"}}}
