from typing import List, Tuple
from routekit.parse_edge import parse_edge

def parse_network(text: str) -> List[Tuple[str, str, int]]:
    """
    Parses a multi-line network file into a list of roads.
    Lines starting with # are comments and should be ignored.
    Empty lines should also be ignored.
    """
    roads = []
    for i, line in enumerate(text.splitlines(), 1):
        # Remove comments and whitespace
        content = line.split('#', 1)[0].strip()
        if not content:
            continue
        try:
            roads.append(parse_edge(content))
        except ValueError as e:
            raise ValueError(f"line {i}: {e}") from e
    return roads
